pub(crate) const XKB_KEYSYM_UNICODE_OFFSET: u32 = 0x1000000;
#[inline]
fn get_name_bytes(offset: u32) -> &'static [u8] {
    let start = offset as usize;
    let rest = &KEYSYM_NAMES[start..];
    let end = rest.iter().position(|&b| b == 0).unwrap_or(rest.len());
    &rest[..end]
}
pub(crate) fn keysym_get_name(ks: u32) -> Option<Cow<'static, str>> {
    let name = Keysym::new(ks).name()?;
    Some(match name.strip_prefix("XK_") {
        Some(name) => Cow::Borrowed(name),
        None => Cow::Owned(name.replacen("XK_", "", 1)),
    })
}
fn lookup_name(name: &[u8], insensitive: bool) -> Option<u32> {
    let matches = |&(offset, _): &(u32, u32)| {
        let stored = get_name_bytes(offset);
        if insensitive {
            stored.eq_ignore_ascii_case(name)
        } else {
            stored == name
        }
    };
    if insensitive {
        NAME_INDEX
            .iter()
            .filter(|entry| matches(entry))
            .max_by_key(|entry| entry.0)
            .map(|entry| entry.1)
    } else {
        let end = NAME_INDEX.partition_point(|entry| get_name_bytes(entry.0) <= name);
        end.checked_sub(1)
            .map(|index| NAME_INDEX[index])
            .filter(matches)
            .map(|entry| entry.1)
    }
}
fn parse_keysym_hex(s: &[u8], out: &mut u32) -> bool {
    let slice = if s.len() > 8 { &s[..8] } else { s };
    let (val, count) = super::parser::parse_hex_u32(slice);
    *out = val;
    count > 0 && s.get(count as usize).copied() == Some(0)
}
pub(crate) fn xkb_keysym_from_name(name: &[u8], flags: u32) -> Option<u32> {
    if flags & !XKB_KEYSYM_CASE_INSENSITIVE != 0 {
        return None;
    }
    let mut val = 0;
    let icase = flags & XKB_KEYSYM_CASE_INSENSITIVE != 0;
    let name_bytes = name.split(|&byte| byte == 0).next()?;
    let named = lookup_name(name_bytes, icase);
    if named.is_some() {
        return named;
    }
    if name_bytes.first() == Some(&b'U') || (icase && name_bytes.first() == Some(&b'u')) {
        let rest_start = 1;
        let rest = &name[rest_start..];
        if !parse_keysym_hex(rest, &mut val) {
            return None;
        }
        return Some(if val > 0xff_u32 && val <= 0x10ffff_u32 {
            XKB_KEYSYM_UNICODE_OFFSET.wrapping_add(val)
        } else {
            codepoint_to_keysym(val).unwrap_or(0)
        });
    } else if name_bytes.first() == Some(&b'0')
        && (name_bytes.get(1) == Some(&b'x') || (icase && name_bytes.get(1) == Some(&b'X')))
    {
        let rest = &name[2..];
        if !parse_keysym_hex(rest, &mut val) || val > XKB_KEYSYM_MAX {
            return None;
        }
        return Some(val);
    }
    if name_bytes.starts_with(b"XF86_")
        || (icase
            && name_bytes
                .get(..5)
                .is_some_and(|s| s.eq_ignore_ascii_case(b"XF86_")))
    {
        let mut tmp_buf: Vec<u8> = Vec::with_capacity(name.len());
        tmp_buf.extend_from_slice(&name_bytes[..4]); // "XF86"
        tmp_buf.extend_from_slice(&name_bytes[5..]); // skip underscore
        tmp_buf.push(0); // null terminator
        return xkb_keysym_from_name(&tmp_buf, flags);
    }
    None
}
pub(crate) fn xkb_keysym_is_keypad(keysym: u32) -> bool {
    Keysym::new(keysym).is_keypad_key()
}
pub(crate) const XKB_KEY_XF86_NUMERIC_0: u32 = 0x10081200;
pub(crate) const XKB_KEY_XF86_NUMERIC_9: u32 = 0x10081209;
pub(crate) const XKB_KEY_XF86_NUMERIC_STAR: u32 = 268964362;
pub(crate) const XKB_KEY_XF86_NUMERIC_POUND: u32 = 268964363;
pub fn keysym_to_char(keysym: u32) -> Option<char> {
    let codepoint = keysym_to_codepoint(keysym)?;
    char::from_u32(codepoint)
}
pub fn keysym_to_codepoint(keysym: u32) -> Option<u32> {
    if (XKB_KEY_XF86_NUMERIC_0..=XKB_KEY_XF86_NUMERIC_9).contains(&keysym) {
        return Some(keysym - XKB_KEY_XF86_NUMERIC_0 + 0x30); // '0' to '9'
    }
    match keysym {
        XKB_KEY_XF86_NUMERIC_STAR => return Some(0x2A), // '*'
        XKB_KEY_XF86_NUMERIC_POUND => return Some(0x23), // '#'
        _ => {}
    }
    #[rustfmt::skip]
    static DEAD_KEYSYM_TO_COMBINING: &[(u32, u16)] = &[(0xfe50,0x0300),(0xfe51,0x0301),(0xfe52,0x0302),(0xfe53,0x0303),(0xfe54,0x0304),(0xfe55,0x0306),(0xfe56,0x0307),(0xfe57,0x0308),(0xfe58,0x030A),(0xfe59,0x030B),(0xfe5a,0x030C),(0xfe5b,0x0327),(0xfe5c,0x0328),(0xfe5d,0x0345),(0xfe5e,0x3099),(0xfe5f,0x309A),(0xfe60,0x0323),(0xfe61,0x0309),(0xfe62,0x031B),(0xfe63,0x0338),(0xfe64,0x0313),(0xfe65,0x0314),(0xfe66,0x030F),(0xfe67,0x0325),(0xfe68,0x0332),(0xfe69,0x032D),(0xfe6a,0x0330),(0xfe6b,0x032E),(0xfe6c,0x0324),(0xfe6d,0x0311),(0xfe6e,0x0326),(0xfe6f,0x00A4),(0xfe80,0x0061),(0xfe81,0x0041),(0xfe82,0x0065),(0xfe83,0x0045),(0xfe84,0x0069),(0xfe85,0x0049),(0xfe86,0x006F),(0xfe87,0x004F),(0xfe88,0x0075),(0xfe89,0x0055),(0xfe8a,0x0259),(0xfe8b,0x018F),(0xfe8c,0x03B1),(0xfe8d,0x0654),(0xfe90,0x0331),(0xfe91,0x030D),(0xfe92,0x0329),(0xfe93,0x0338)];
    if let Ok(idx) = DEAD_KEYSYM_TO_COMBINING.binary_search_by_key(&keysym, |e| e.0) {
        return Some(DEAD_KEYSYM_TO_COMBINING[idx].1 as u32);
    }
    Keysym::new(keysym).key_char().map(u32::from)
}
pub fn codepoint_to_keysym(ucs: u32) -> Option<u32> {
    if ucs == 0 {
        return None;
    }
    let ch = char::from_u32(ucs)?;
    if ucs & 0xfffe == 0xfffe || (0xfdd0..=0xfdef).contains(&ucs) {
        return Some(ucs | XKB_KEYSYM_UNICODE_OFFSET);
    }
    let ks = Keysym::from_char(ch).raw();
    (ks != 0).then_some(ks)
}
fn case_char(ks: u32) -> Option<char> {
    if ks > 0x13be && !(0x1000100..=0x101f189).contains(&ks) {
        return None;
    }
    keysym_to_char(ks)
}
pub(crate) fn xkb_keysym_to_upper(ks: u32) -> u32 {
    let Some(ch) = case_char(ks) else {
        return ks;
    };
    let cp = match ch as u32 {
        0xdf => 0x1e9e,
        cp @ 0x1f80..=0x1f87 | cp @ 0x1f90..=0x1f97 | cp @ 0x1fa0..=0x1fa7 => cp + 8,
        0x1fb3 => 0x1fbc,
        0x1fc3 => 0x1fcc,
        0x1ff3 => 0x1ffc,
        0xa7cf | 0xa7d3 | 0xa7d5 => ch as u32 - 1,
        cp @ 0x16ebb..=0x16ed3 => cp - 0x1b,
        _ => {
            let mut upper = ch.to_uppercase();
            let Some(first) = upper.next() else {
                return ks;
            };
            if upper.next().is_some() {
                return ks;
            }
            first as u32
        }
    };
    if cp == ch as u32 {
        ks
    } else if ks >= 0x1000100 && cp >= 0x100 {
        XKB_KEYSYM_UNICODE_OFFSET + cp
    } else {
        codepoint_to_keysym(cp).unwrap_or(ks)
    }
}
pub(crate) fn xkb_keysym_is_lower(ks: u32) -> bool {
    case_char(ks).is_some_and(|ch| match ch as u32 {
        0x295 => false,
        0xa7cf | 0xa7f1 | 0x16ebb..=0x16ed3 => true,
        _ => ch.is_lowercase(),
    })
}
pub(crate) fn xkb_keysym_is_upper_or_title(ks: u32) -> bool {
    case_char(ks).is_some_and(|ch| match ch as u32 {
        0x1c5 | 0x1c8 | 0x1cb | 0x1f2 => true,
        0x1f88..=0x1f8f | 0x1f98..=0x1f9f | 0x1fa8..=0x1faf => true,
        0x1fbc | 0x1fcc | 0x1ffc | 0xa7ce | 0xa7d2 | 0xa7d4 | 0x16ea0..=0x16eb8 => true,
        _ => ch.is_uppercase(),
    })
}
